<?php if(!defined('ABSPATH'))exit;$groups=dre_price_groups(get_the_content(),dre_lang());$total=array_sum(array_map(fn($g)=>count($g['items']),$groups));?>
<section class="content-section container prices-section"><p class="price-lead"><?php echo esc_html(dre_e('price_intro'));?></p><div class="price-category-nav" aria-label="<?php echo esc_attr(dre_t('prices'));?>"><?php foreach($groups as $group):?><a href="#price-<?php echo esc_attr($group['key']);?>" data-price-category="price-<?php echo esc_attr($group['key']);?>"><?php echo esc_html($group['title']);?></a><?php endforeach;?></div><div class="prices-layout"><div><div class="price-search-panel"><label for="price-search"><?php echo esc_html(dre_t('search_prices'));?></label><div class="price-search-input"><input id="price-search" type="search" placeholder="<?php echo esc_attr(dre_t('search_prices'));?>" autocomplete="off"><button type="button" id="price-clear" hidden><?php echo esc_html(dre_e('clear'));?></button></div><div class="price-controls"><span id="price-result-count" role="status" aria-live="polite"><?php echo esc_html(dre_e('items').': '.$total);?></span><div><button type="button" data-price-expand><?php echo esc_html(dre_e('expand'));?></button><button type="button" data-price-collapse><?php echo esc_html(dre_e('collapse'));?></button></div></div></div><p class="price-empty" id="price-empty" hidden><?php echo esc_html(dre_e('no_results'));?></p><div class="price-accordion" id="price-accordion"><?php foreach($groups as $index=>$group):?><details class="price-category" id="price-<?php echo esc_attr($group['key']);?>" <?php if(!$index)echo 'open';?>><summary><span><strong><?php echo esc_html($group['title']);?></strong><small><?php echo esc_html(dre_e('items').': '.count($group['items']));?></small></span><span class="price-chevron"><?php echo dre_icon('chevron');?></span></summary><div class="price-category-body"><table><caption class="screen-reader-text"><?php echo esc_html($group['title']);?></caption><thead><tr><th scope="col"><?php echo esc_html(dre_e('price_service'));?></th><th scope="col"><?php echo esc_html(dre_e('price_amount'));?></th></tr></thead><tbody><?php foreach($group['items'] as $item):?><tr data-price-row data-search="<?php echo esc_attr($group['title'].' '.$item['context'].' '.$item['name']);?>"><td><?php if($item['context']):?><span class="price-context"><?php echo esc_html($item['context']);?></span><?php endif;?><span><?php echo esc_html($item['name']);?></span></td><td data-source-price="<?php echo esc_attr($item['price']);?>"><?php echo esc_html(dre_price_display($item['price']));?></td></tr><?php endforeach;?></tbody></table></div></details><?php endforeach;?></div><div class="notice price-bottom-note"><?php echo esc_html(dre_e('price_notice'));?></div></div><?php dre_sidebar();?></div></section>
